#!/usr/bin/env python3
"""Generate data/essays.js from data/essays.json for direct index.html preview."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parent
json_path = ROOT / "data" / "essays.json"
js_path = ROOT / "data" / "essays.js"
records = json.loads(json_path.read_text(encoding="utf-8"))
if not isinstance(records, list):
    raise SystemExit("data/essays.json must contain a JSON array")
js_path.write_text(
    "/* Generated by sync_data.py from essays.json. */\n"
    "window.COMPOSITION_ESSAYS = "
    + json.dumps(records, ensure_ascii=False, separators=(",", ":"))
    + ";\n",
    encoding="utf-8",
)
print(f"Generated {js_path.relative_to(ROOT)} with {len(records)} records.")
